/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3table {	public static final class Attr {		public static final String captionSide = "caption-side";		public static final String collapse = "border-collapse";		public static final String spacing = "border-spacing";		public static final String emptyCells = "empty-cells";		public static final String layout = "table-layout";	}	public Value side(boolean bottom) {		String value = bottom ? "bottom" : "top";		return new Value().name(Attr.captionSide).text(value);	}	public Value collapse(boolean collapse) {		String value = collapse ? "collapse" : "separate";		return new Value().name(Attr.collapse).text(value);	}	public Value spacing(String shorthand) {		return new Value().name(Attr.spacing).text(shorthand);	}	public Value emptyCells(boolean show) {		String value =  show ? "show" : "hide";		return new Value().name(Attr.emptyCells).text(value);	}	public Value layout(boolean fixed) {		String value = fixed ? "fixed" : "auto";		return new Value().name(Attr.layout).text(value);	}}